INSERT INTO `nodes` VALUES ('11f1d907-607e-4a51-804f-d796cc074a6c','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791213463798,1791213463798),('23afd710-5e7b-43fe-bf18-ea45c3024462','2026-10-01','# 2026-10-01\n\n## 今天\n\n- [ ] 试用卡片：把 [[韧性设计原则]] 拖到顺手的位置\n- [ ] 按 Ctrl+K 搜索「韧性」','2026 10 01','2026 10 01 今天 试用卡片 把 韧性设计原则 拖到顺手的位置 按 ctrl k 搜索 韧性','','daily',NULL,NULL,0,0,NULL,'2026-10-01',0,1790849308470,1790849308558),('3051859b-e162-4552-8061-f7d85332be9b','Markdown 与双链语法','# Markdown 与双链语法\n\n## 双向链接\n\n`[[笔记标题]]` 建立链接；`[[标题|显示文字]]` 起别名；`[[标题#小节]]` 指向小节。\n\n## 标签\n\n正文里写 `#标签名` 会自动成为标签，也可以在标题下方手动添加。\n\n## 内容块\n\n标题、列表、待办、引用、代码块、表格、分割线、图片、双向链接都可以直接写。\n\n| 语法 | 效果 |\n| --- | --- |\n| `**粗体**` | **粗体** |\n| `` `代码` `` | `代码` |','markdown 与双链语法','markdown 与双链语法 双向链接 笔记标题 建立链接 标题 显示文字 起别名 标题 小节 指向小节 标签 正文里写 标签名 会自动成为标签 也可以在标题下方手动添加 内容块 标题 列表 待办 引用 代码块 表格 分割线 图片 双向链接都可以直接写 语法 效果 粗体 粗体 代码 代码','','note',NULL,NULL,0,0,NULL,NULL,0,1790849308295,1790849308372),('381ccc2e-2e1c-444e-a08b-f098391a32de','韧性设计原则','# 韧性设计原则\n\n系统失去韧性，通常不是因为它不够强，而是因为它没有冗余、没有反馈、无法回滚。\n\n## 冗余\n\n本地 SQLite 是权威数据源，同时维护一份 Markdown 镜像；每天自动快照，保留 7 天。\n\n## 反馈\n\n反向链接让你看到「谁在用我的想法」；空间位置让你看到「想法之间的关系」。\n\n相关：[[欢迎使用 thisnode]]','韧性设计原则','韧性设计原则 系统失去韧性 通常不是因为它不够强 而是因为它没有冗余 没有反馈 无法回滚 冗余 本地 sqlite 是权威数据源 同时维护一份 markdown 镜像 每天自动快照 保留 7 天 反馈 反向链接让你看到 谁在用我的想法 空间位置让你看到 想法之间的关系 相关 欢迎使用 thisnode','','note',NULL,NULL,0,0,NULL,NULL,0,1790849308160,1790849308238),('3cc33320-a860-4ecd-b943-c08fe3e48254','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791215507256,1791215507256),('3e544b22-021e-46f6-813e-434bbb0fb469','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791213172974,1791213172974),('4af0a2da-e6ea-4845-9103-843899d7bd29','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791212787182,1791212787182),('5561ae20-aa2c-448d-9cf1-c856ef5f429d','本地文件与 Markdown 镜像','# 本地文件与 Markdown 镜像\n\n每篇笔记都会同步写入 `~/.thisnode/notes/` 下的一个 `.md` 文件，可以直接用 Obsidian / VS Code 打开。\n\n在外部编辑并保存后，回到应用 4 秒内会自动同步进来，并重建链接与全文索引。','本地文件与 markdown 镜像','本地文件与 markdown 镜像 每篇笔记都会同步写入 thisnode notes 下的一个 md 文件 可以直接用 obsidian vs code 打开 在外部编辑并保存后 回到应用 4 秒内会自动同步进来 并重建链接与全文索引','','note',NULL,NULL,0,0,NULL,NULL,0,1790849308395,1790849308443),('5c95d642-0345-46f3-bfb1-495ed4f65b0d','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791212669270,1791212669270),('61b60529-1b6b-4c59-a170-6e885c8535d9','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791215797638,1791215797638),('632ae4fd-61e3-4c0c-b358-16c2e5ff8df9','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791259266828,1791259266828),('634772de-0a93-4749-87dc-f4b02ce84272','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791215762361,1791215762361),('71f6494e-5579-4336-ab90-2d1533d7cf55','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791215523453,1791215523453),('72a5b273-5e4a-4011-9c82-1832074e4a63','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791212626467,1791212626467),('74553b9f-dd5d-4f70-8b8b-67504e626177','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791213105454,1791213105454),('830479c9-7f6b-4d04-b8f8-9f19add7cd3d','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791213200347,1791213200347),('8f84e982-d59b-48ef-b492-c256364b28fe','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791213550440,1791213550440),('b69e799c-a310-4bf7-b1d9-a293f76b40ef','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791251169516,1791251169516),('b9d57b69-d3fc-4e81-b58d-119a01291d5e','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791213534319,1791213534319),('bf80f46e-806c-41e2-8ca0-2e0b53323509','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791259290735,1791259290735),('ce682334-2f93-4be9-85c8-4dd001debdb4','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791212590260,1791212590260),('cf9d3ca4-7d40-436c-aab5-cf2eec6f78e7','欢迎使用 thisnode','## 先写链接，再建笔记\n\n正文里写 `[[某个概念]]`，即使那篇笔记还不存在也可以；之后创建它，链接会自动接上。\n\n比如现在指向 [[韧性设计原则]]。\n\n# 欢迎使用 thisnode\n\n这是一篇**笔记**。下面每一块都是一个可以随手摆放、随手书写的**卡片**：\n\n- 双击页面空白处 → 新建一张卡片\n- 在卡片里直接打字 → 内容就是这篇笔记的内容\n- 拖动卡片 → 摆到你顺手的位置\n- `Ctrl+V` → 剪贴板内容变成一张卡片\n\n## 卡片属于这篇笔记\n\n一篇笔记就是一个页面，页面上的卡片装的是这篇笔记的内容片段。\n不想看的卡片可以折叠（标题栏右侧箭头），折叠后只剩一条标题。','欢迎使用 thisnode','先写链接 再建笔记 正文里写 某个概念 即使那篇笔记还不存在也可以 之后创建它 链接会自动接上 比如现在指向 韧性设计原则 欢迎使用 thisnode 这是一篇 笔记 下面每一块都是一个可以随手摆放 随手书写的 卡片 双击页面空白处 新建一张卡片 在卡片里直接打字 内容就是这篇笔记的内容 拖动卡片 摆到你顺手的位置 ctrl v 剪贴板内容变成一张卡片 卡片属于这篇笔记 一篇笔记就是一个页面 页面上的卡片装的是这篇笔记的内容片段 不想看的卡片可以折叠 标题栏右侧箭头 折叠后只剩一条标题','','note',NULL,NULL,0,0,NULL,NULL,0,1790849308006,1790849308135),('dca07ca9-39e6-4707-95b4-d25063fd2dbb','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791213239195,1791213239195),('e1309234-c6c5-4012-a565-e8bb93c976ad','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791284588040,1791284588040),('ed0c6497-2f17-45ab-a549-b1af0b4d77c9','无标题笔记','','无标题笔记','','','note',NULL,NULL,0,0,NULL,NULL,0,1791251132328,1791251132328);
